```

### 动态高度调整算法

```typescript
function calculateWindowHeight(todoCount: number): number {
  const baseHeight = 120;      // 头部 + 底部固定高度
  const itemHeight = 48;       // 每个任务项高度
  const padding = 16;          // 内边距
  const maxHeight = 800;       // 最大高度
  const minHeight = 200;       // 最小高度

  const calculatedHeight = baseHeight + (todoCount * itemHeight) + padding;
  return Math.min(Math.max(calculatedHeight, minHeight), maxHeight);
}
```

